from lib import *
S = SS('v8')
steps = [
    step("共享线程池 vs 舱壁。服务有 20 个工作线程,A 类请求调用快的 D1(10 ms),B 类调用 D2;D2 在 2 秒之后每个请求挂 2 秒;client 以 100 个/秒发 8 秒,等 1 秒放弃;只统计第 3 到 8 秒到达的请求(A 类 350 个、B 类 150 个)。共享线程池:A 类 1 s 内成功 0.0%,B 类 150 个全部超时,线程全被 D2 占住,连没有问题的 A 类都饿死了。信号量舱壁(调 D2 最多 5 个):A 类 100.0%,中位数 15 ms、p99 17 ms;B 类 140 个被立刻拒绝、10 个超时。独立线程池(14 + 6):A 类 100.0%,中位数 14 ms、p99 17 ms;B 类 138 个立刻拒绝、12 个超时。舱壁让 B 类自己出问题,不再拖累 A 类。", t=tl(S(1)), mark=lidx(S(1), '共享线程池'), done=lidx(S(1), '信号量舱壁', '独立线程池'), b=bars([['共享池:A 类成功 %', 0, '0.0%'], ['信号量舱壁:A 类成功 %', 100, '100.0%'], ['独立线程池:A 类成功 %', 100, '100.0%'], ['舱壁:B 类被立刻拒绝', 140, '140(信号量)/ 138(线程池)']], 150, mark=[0], done=[1, 2], cur=[3]), kv=KV([['共享线程池', 'A 类 0.0% 成功,B 类全部超时'], ['信号量舱壁', 'A 类 100.0%,B 类 140 个被立刻拒绝'], ['独立线程池', 'A 类 100.0%,B 类 138 个被立刻拒绝']], ['共享线程池'])),
    step("Java 的线程池满了怎么办。ThreadPoolExecutor(核心 2、最大 4、队列容量 4),一次提交 20 个各睡 200 ms 的任务,容纳量是 4 个线程 + 4 个排队 = 8 个。AbortPolicy:执行了 8 个(0 到 7),12 个抛 RejectedExecutionException,提交完 20 个用了 0 ms。CallerRunsPolicy:20 个全部执行,其中 3 个在提交者 main 线程里执行,提交完 20 个用了 622 ms(提交被拖慢,是一种背压)。DiscardPolicy:执行 8 个(0 到 7),12 个悄悄丢掉。DiscardOldestPolicy:执行 8 个,编号是 0、1、6、7、16、17、18、19,排队里最老的被丢掉,12 个悄悄丢掉。", t=tl(S(2)), mark=lidx(S(2), 'CallerRunsPolicy'), done=lidx(S(2), 'AbortPolicy', 'DiscardPolicy', 'DiscardOldestPolicy'), b=bars([['Abort:执行了', 8, '8(12 个异常)'], ['CallerRuns:执行了', 20, '20(3 个在 main)'], ['Discard:执行了', 8, '8(12 个悄悄丢)'], ['DiscardOldest:执行了', 8, '8(丢最老的)']], 20, done=[0, 2, 3], mark=[1]), kv=KV([['AbortPolicy', '8 执行,12 个异常'], ['CallerRunsPolicy', '20 执行,提交用了 622 ms'], ['DiscardPolicy', '12 个悄悄丢'], ['DiscardOldestPolicy', '执行 0、1、6、7、16、17、18、19']], ['CallerRunsPolicy'])),
    step("网关上的连接被慢上游占满。nginx 1.31.6,worker_connections = 64,/slow 上游每个请求挂 3 秒,/fast 上游马上回;40 个客户端线程不断请求 /slow,同时另一个线程每 100 ms 请求一次 /fast,共 5 秒。不做隔离:/fast 探测 47 次,成功 81%,9 次连接被拒或重置,nginx 的 error.log 里有 632 行 worker_connections are not enough;/slow 把连接占满,和它无关的 /fast 也受影响。给 /slow 加 limit_conn 6(同时最多 6 个,多的立刻 503):/fast 47 次全部成功(100%),中位数 1.1 ms,error.log 里 0 行,/slow 被立刻 503 的有 3281 次。注意:limit_conn 的键如果用 $server_name 而 server 块没写 server_name,值是空串,nginx 不统计空键的请求,limit_conn 悄悄没有效果(20 个并发请求全部 200)。", t=tl(S(3)), mark=lidx(S(3), '不做隔离'), done=lidx(S(3), '/slow 加 limit_conn 6'), b=bars([['不隔离:/fast 成功 %', 81, '81%'], ['limit_conn:/fast 成功 %', 100, '100%'], ['不隔离:not enough 行数', 632, '632'], ['limit_conn:not enough 行数', 0, '0']], 632, mark=[0, 2], done=[1, 3]), kv=KV([['不做隔离', '/fast 成功 81%,632 行 not enough'], ['/slow limit_conn 6', '/fast 100%,/slow 3281 次 503'], ['$server_name 做键', '没写 server_name 时 limit_conn 悄悄无效']], ['/slow limit_conn 6'])),
]
A = mkartv('v8', 8, '微服务,弹性,舱壁,线程池,连接池,nginx,真实验证,动画演示',
    '实测舱壁:共享 20 线程池里 D2 变慢后,没问题的 A 类请求 1 秒内成功 0.0%;信号量舱壁和独立线程池让 A 类保持 100.0%;Java 线程池四种拒绝策略(执行 8 / 20 / 8 / 8);nginx worker_connections 被慢上游占满时 /fast 成功只有 81%,给 /slow 加 limit_conn 6 后 100%。',
    '一个依赖变慢,怎么拖垮整个服务?线程池隔离和信号量隔离各怎么做?Java 线程池满了该选哪种拒绝策略?网关上又怎么防止慢上游把连接占满?这篇用本机的小服务、Java 和 nginx 量出来。',
    [('0.0% 对 100.0%', 'D2 变慢后,共享线程池与舱壁(信号量或独立线程池)下,与 D2 无关的 A 类请求 1 秒内的成功率'), ('622 ms', 'CallerRunsPolicy 提交 20 个任务用的时间:拒绝策略把提交者也拖慢了(AbortPolicy 是 0 ms)'), ('81% → 100%', 'nginx worker_connections = 64 被 /slow 占满时,不相关的 /fast 的探测成功率,加 limit_conn 6 之后')],
    [('共享线程池与舱壁', '<p>一个依赖变慢会占满共享的线程,没有问题的请求也饿死;给每个依赖划定上限后,慢的只影响自己。</p>'),
     ('Java 线程池的拒绝策略', '<p>Abort 抛异常,CallerRuns 让提交者执行(背压),Discard 悄悄丢最新的,DiscardOldest 悄悄丢最老的。</p>'),
     ('网关上的连接', '<p>慢上游占满 worker_connections 时无关的路由也受影响;限制慢路由的并发可以隔离。limit_conn 的键不能是空串。</p>')],
    steps,
    [ENV_V + '。第一节的“服务”是我写的 20 个线程的小池子(Python),D1 / D2 是本进程里的 http.server;信号量舱壁是 B 类调用 D2 前非阻塞地拿最多 5 个的信号量;独立线程池是 14 + 6 个线程各有一个队列(B 的队列最多排 10 个);第二节是 OpenJDK 17.0.20.1 的 ThreadPoolExecutor(java Reject.java 单文件运行);第三节是 Homebrew 的 nginx 1.31.6(worker_connections 改成 64),40 个 client 线程',
     '没有验证:Resilience4j / Hystrix 的 Bulkhead 实现细节;线程池隔离时线程切换的开销;ThreadPoolExecutor 自定义拒绝策略(阻塞入队);nginx 之外的网关;第一节的 B 类 1 s 内都不会成功(D2 要 2 s),所以没有比较 B 类的成功率'],
    '舱壁与连接池耗尽')
